<?php declare(strict_types=1);
use Kulturhus\Verein\Settings\GeneralRequests;
use Kulturhus\Verein\SettingsSchema;
$gt=static fn(string $source):string=>\Kulturhus\Native\Language\GeneralSettingsMessages::text($source,$generalMessages);
$gkeep=[];foreach(['settings_draft','settings_receipt','settings_revision','settings_history_q','settings_history_page','settings_revisions_page']as$key)if(is_string($_GET[$key]??null))$gkeep[$key]=$_GET[$key];
$gurl=static fn(array $query=[]):string=>url(['view'=>'settings','section'=>$generalSection]+array_replace($gkeep,$query));
$gscalar=static fn(mixed $value):string=>is_string($value)||is_int($value)||is_bool($value)?(string)$value:(is_array($value)?GeneralRequests::json($value):'');
$gdescribe=static function(array $data)use($gt,$gscalar,$generalSection):void{
    $value=static function(mixed $raw):string{return is_bool($raw)?($raw?'Ja':'Nein'):(is_scalar($raw)?(string)$raw:'');};
    ?><details class="general-settings-values"><summary><?= e($gt('Vollständige Werte')) ?></summary>
    <?php if($generalSection==='club'): ?><dl class="general-settings-description"><?php foreach(SettingsSchema::fields('club')as$key=>$field){if(in_array($key,['show_phone','show_email'],true))continue;$raw=$data[$key]??''; ?><dt><?= e($gt($field[0])) ?></dt><dd><?= e($field[1]==='checkbox'?$gt($value((bool)$raw)):$gscalar($raw)) ?></dd><?php } ?></dl>
    <?php else:if($generalSection==='salutations'): ?><dl class="general-settings-description"><dt><?= e($gt('Standard-Briefanrede')) ?></dt><dd><?= e($gt(($data['mode']??'')==='formal'?'Formell':'Persönlich')) ?></dd><dt><?= e($gt('Titel (ein Eintrag je Zeile)')) ?></dt><dd><?= e($gscalar($data['titles']??'')) ?></dd></dl><?php endif;
    foreach(is_array($data['rows']??null)?$data['rows']:[]as$index=>$row){if(!is_array($row))continue; ?><section><h4><?= e($gt($generalSection==='fields'?'Individuelles Feld':'Briefanrede')) ?> <?= (int)$index+1 ?></h4><dl class="general-settings-description"><?php $labels=$generalSection==='fields'?['name'=>'Feldname','type'=>'Typ','options'=>'Auswahlwerte (eine Zeile je Wert)','required'=>'Pflichtfeld','id'=>'Feldkennung']:['name'=>'Anrede','personal'=>'Persönlich','formal'=>'Formell'];foreach($labels as$key=>$label){$raw=$row[$key]??'';if($key==='type')$shown=$gt(['text'=>'Text','number'=>'Zahl','date'=>'Datum','checkbox'=>'Ja/Nein','select'=>'Auswahl'][$gscalar($raw)]??$gscalar($raw));elseif($key==='required')$shown=$gt(in_array($raw,[true,1,'1'],true)?'Ja':'Nein');else $shown=$gscalar($raw); ?><dt><?= e($gt($label)) ?></dt><dd><?= e($shown) ?></dd><?php } ?></dl></section><?php }
    endif ?></details><?php
};
$greview=static function(array $review)use($gdescribe,$gt):void{ ?><p><?= e($gt('Gespeicherte Fassung')) ?>: <?= e($review['current']['version']??'') ?></p><h4><?= e($gt('Damals gelesener Stand')) ?></h4><?php $gdescribe($review['current']['data']??[]); ?><h4><?= e($gt('Nach Bestätigung gespeicherte Werte')) ?></h4><?php $gdescribe($review['normalized']??[]); };
$gfield=static function(string $name,array $field,mixed $value)use($gt,$gscalar):void{
    [$label,$type,$limit,$default]=$field;$value=$gscalar($value);$id='general-'.substr(hash('sha256',$name),0,20);$required=$field[4]??false;
    if($type==='checkbox'){echo hidden($name,'0');?><label class="general-settings-check" for="<?= e($id) ?>"><input class="check" id="<?= e($id) ?>" type="checkbox" name="<?= e($name) ?>" value="1" <?= in_array($value,['1'],true)?'checked':'' ?>> <span><?= e($gt($label)) ?></span></label><?php return;}
    ?><label class="general-settings-field" for="<?= e($id) ?>"><span><?= e($gt($label)) ?><?= $required?' *':'' ?></span>
    <?php if($type==='select'): ?><select class="form-control" id="<?= e($id) ?>" name="<?= e($name) ?>"><?php if(!array_key_exists($value,$limit)): ?><option value="<?= e($value) ?>" selected><?= e($value) ?></option><?php endif ?><?php foreach($limit as$key=>$text): ?><option value="<?= e($key) ?>" <?= $value===(string)$key?'selected':'' ?>><?= e($gt($text)) ?></option><?php endforeach ?></select>
    <?php elseif($type==='textarea'): ?><textarea class="form-control" id="<?= e($id) ?>" name="<?= e($name) ?>" rows="4" <?= $required?'required':'' ?> data-max-characters="<?= (int)$limit ?>"><?= e($value) ?></textarea>
    <?php else: ?><input class="form-control" id="<?= e($id) ?>" name="<?= e($name) ?>" type="<?= e(in_array($type,['email','url'],true)?$type:'text') ?>" value="<?= e($value) ?>" <?= $required?'required':'' ?> data-max-characters="<?= (int)$limit ?>"><?php endif ?>
    <?php if($type!=='select'): ?><small><?= e($gt('Zeichenhöchstzahl')) ?>: <?= (int)$limit ?></small><?php endif ?></label><?php
};
$gpages=static function(array $list,string $key,array $extra=[])use($gurl,$gt,$generalSection,$gkeep):void{
    $extra=array_replace($gkeep,$extra);unset($extra[$key]);
    ?><form method="get" class="general-settings-page-form"><?= hidden('view','settings').hidden('section',$generalSection) ?><?php foreach($extra as$name=>$value)echo hidden($name,$value); ?><label><?= e($gt('Seite')) ?><input class="form-control" name="<?= e($key) ?>" value="<?= e($list['page_input']) ?>" inputmode="numeric"></label><button class="btn btn-outline theme-secondary"><?= e($gt('Seite öffnen')) ?></button><span><?= e($list['total']) ?> · <?= e($list['pages']) ?></span><?php if(($list['page']??null)>1): ?><a class="btn btn-outline theme-secondary" href="<?= e($gurl([$key=>(string)($list['page']-1)]+$extra)) ?>"><?= e($gt('Zurück')) ?></a><?php endif ?><?php if(($list['page']??null)!==null&&$list['page']<$list['pages']): ?><a class="btn btn-outline theme-secondary" href="<?= e($gurl([$key=>(string)($list['page']+1)]+$extra)) ?>"><?= e($gt('Weiter')) ?></a><?php endif ?></form><?php
};
?>
<link rel="stylesheet" href="general-settings-native.css?v=1">
<div class="content general-settings-native" data-general-settings data-general-section="<?= e($generalSection) ?>">
<div class="page-heading"><h1><?= e($gt(SettingsSchema::SECTIONS[$generalSection])) ?></h1></div>
<?php if(!$generalState)return; ?>
<?php if(isset($generalState['errors']['receipt'])): ?><p role="alert"><?= e($gt($generalState['errors']['receipt'])) ?></p><?php endif ?>
<section class="card general-settings-current"><h2><?= e($gt('Aktueller gespeicherter Stand')) ?></h2><p><?= e($gt('Gespeicherte Fassung')) ?>: <strong data-current-version><?= e($generalState['current']['version']) ?></strong></p><?php if($generalSection==='club'): ?><p><?= e($generalState['current']['data']['name']??'') ?></p><p><?= e($gt('Vereinsdaten verändern keine früheren Briefe, Belege oder veröffentlichten Originale.')) ?></p><?php endif ?><?php $gdescribe($generalState['current']['data']); ?></section>
<?php if($generalState['receipt']):$gr=$generalState['receipt']; ?>
<section class="card" data-settings-original><h2><?= e($gt('Angenommene Originalbestätigung')) ?></h2><dl><dt><?= e($gt('Vorgang')) ?></dt><dd><code data-original-key><?= e($gr['key']) ?></code></dd><dt><?= e($gt('Gespeicherte Fassung')) ?></dt><dd><?= e($gr['result']['version']) ?></dd><dt><?= e($gt('Zeitpunkt')) ?></dt><dd><?= e($gr['created_at']) ?></dd><dt><?= e($gt('Konto')) ?></dt><dd><?= e($gr['actor_id']) ?></dd><dt>SHA-256</dt><dd><code><?= e($gr['sha256']) ?></code></dd></dl>
<a class="btn btn-outline theme-secondary" data-settings-original-download data-navigation-native href="<?= e($gurl(['settings_original'=>$gr['key']])) ?>"><?= e($gt('Original-JSON herunterladen')) ?></a>
<?php foreach(['input'=>'Eingaben','review'=>'Prüfung','result'=>'Tatsächliches Ergebnis']as$key=>$label): ?><h3><?= e($gt($label)) ?></h3><?php if($key==='review')$greview($gr[$key]);else $gdescribe($gr[$key]['data']??[]);endforeach ?>
<a class="btn btn-solid theme-primary" href="<?= e(url(['view'=>'settings','section'=>$generalSection])) ?>"><?= e($gt('Weitere Einstellungen bearbeiten')) ?></a></section>
<?php endif ?>
<?php if($generalDraft&&$generalDraft['accepted']===null):$gd=$generalDraft;$gdata=is_array($gd['input']['data']??null)?$gd['input']['data']:[]; ?>
<section class="card" data-settings-compose><h2><?= e($gt('Ungespeicherter Entwurf')) ?></h2><p><?= e($gt('Noch nicht gespeichert. Zeilenaktionen ändern nur diesen Entwurf.')) ?></p><p><?= e($gt('Entwurfskennung')) ?>: <code data-settings-key><?= e($gd['key']) ?></code></p>
<a class="btn btn-outline theme-secondary" data-settings-check href="<?= e($gurl(['settings_draft'=>$gd['id'],'settings_receipt'=>$gd['key']])) ?>"><?= e($gt('Ursprünglichen Ausgang lesend prüfen')) ?></a>
<?php if($gd['pending']): ?><p role="status"><?= e($gt('Ausgang noch nicht bestätigt. Zuerst die ursprüngliche Kennung lesend prüfen.')) ?></p><?php endif ?>
<?php if($gd['conflicted']): ?><p role="status"><?= e($gt('Diese frühere Prüfung ist nicht mehr aktuell. Die vorgeschlagenen Werte bleiben erhalten.')) ?></p><?php endif ?>
<form method="post" data-settings-edit><?= csrf().hidden('action','general-settings-native').hidden('settings_draft',$gd['id']) ?>
<?php if($generalSection==='club'):
foreach([['Name & Eintragung',['name','registered','register']],['Anschrift & Kontakt',['street','address2','postcode','city','phone','email','website']],['Weitere Vereinsangaben',['alternate','type','category']]]as[$title,$fields]): ?><fieldset><legend><?= e($gt($title)) ?></legend><div class="general-settings-grid"><?php foreach($fields as$key){$field=SettingsSchema::fields('club')[$key];$gfield('data['.$key.']',$field,$gdata[$key]??$field[3]);} ?></div></fieldset><?php endforeach;
foreach(['show_phone','show_email']as$key)echo hidden('data['.$key.']',!empty($gdata[$key])?'1':'0');
else:
if($generalSection==='salutations'): ?><div class="general-settings-grid"><?php $gfield('data[mode]',['Standard-Briefanrede','select',['personal'=>'Persönlich','formal'=>'Formell'],'personal'],$gdata['mode']??'personal');$gfield('data[titles]',['Titel (ein Eintrag je Zeile)','textarea',2000,''],$gdata['titles']??''); ?></div><p><?= e($gt('Höchstens 30 Anreden. Variablen bleiben unverändert, zum Beispiel {{VORNAME}} und {{NACHNAME}}.')) ?></p><?php else: ?><p><?= e($gt('Höchstens 50 Felder. Umbenennen und Umordnen erhalten die Feldkennung. Frühere Profilwerte werden nicht geändert; entfernte Angaben bleiben dort als frühere Angaben lesbar.')) ?></p><?php endif ?>
<input type="hidden" name="settings_rows_present" value="1"><div data-general-settings-rows>
<?php $grows=is_array($gdata['rows']??null)?array_values($gdata['rows']):[];foreach($grows as$index=>$row):if(!is_array($row))$row=['name'=>$gscalar($row)]; ?>
<fieldset class="general-settings-row" data-settings-row><legend><?= e($gt($generalSection==='fields'?'Individuelles Feld':'Briefanrede')) ?> <?= $index+1 ?></legend>
<?php if($generalSection==='fields'): ?><p><?= e($gt('Feldkennung')) ?>: <code><?= e($gscalar($row['id']??'')) ?></code></p><?= hidden('data[rows]['.$index.'][id]',$gscalar($row['id']??'')) ?><?php endif ?>
<div class="general-settings-grid"><?php $rowFields=$generalSection==='salutations'?['name'=>['Anrede','text',60,''],'personal'=>['Persönlich','text',300,''],'formal'=>['Formell','text',300,'']]:['name'=>['Feldname','text',100,''],'type'=>['Typ','select',['text'=>'Text','number'=>'Zahl','date'=>'Datum','checkbox'=>'Ja/Nein','select'=>'Auswahl'],'text'],'options'=>['Auswahlwerte (eine Zeile je Wert)','textarea',1000,''],'required'=>['Pflichtfeld','checkbox',1,false]];foreach($rowFields as$key=>$field)$gfield('data[rows]['.$index.']['.$key.']',$field,$row[$key]??$field[3]); ?></div>
<div class="general-settings-actions"><?php if($index>0): ?><button class="btn btn-outline theme-secondary" name="settings_intent" value="up:<?= $index ?>" formnovalidate><?= e($gt('Nach oben')) ?></button><?php endif ?><?php if($index<count($grows)-1): ?><button class="btn btn-outline theme-secondary" name="settings_intent" value="down:<?= $index ?>" formnovalidate><?= e($gt('Nach unten')) ?></button><?php endif ?><button class="btn btn-outline theme-secondary" name="settings_intent" value="remove:<?= $index ?>" formnovalidate><?= e($gt('Entfernen')) ?></button></div></fieldset>
<?php endforeach ?></div>
